"thai_prawn_curry": { title: "Thai prawn curry", serves: "4", time: "30 min", category: "🌍 World Cuisine", all_ingredients: ["1 tbls Vegetable Oil","1 chopped Onion","1 tsp Ginger","2 tsp Thai Red Curry Paste","400g Tinned Tomatos","50g Coconut Cream","400g Raw Frozen Prawns","Chopped Coriander"], product_ids: [545,930,9,4141,476,2301], steps: ["Heat the oil in a medium saucepan","Tip in the onion and ginger, then cook for a few mins until softened","Stir in the curry paste, then cook for 1 min more","Pour over the chopped tomatoes and coconut cream","Bring to the boil, then leave to simmer for 5 mins, adding a little boiling water if the mixture gets too thick","Tip in the prawns, then cook for 5-10 mins more, depending on how large they are","Serve alongside some plain rice and sprinkle with a little chopped coriander, if you like ✅"] },
"thai_pumpkin_soup": { title: "Thai pumpkin soup", serves: "4", time: "30 min", category: "🍵 Soup", all_ingredients: ["1.5kg Pumpkin","4 tsp Sunflower Oil","1 sliced Onion","1 tbsp grated Ginger","1 Lemongrass","4 tablespoons Thai Red Curry Paste","400ml Coconut Milk","800ml Vegetable Stock","To taste Lime juice","To taste Sugar","To serve Red Chilli"], product_ids: [9,2314,4141,973,48,476,2301], steps: ["Heat oven to 200C/180C fan/gas 6","Toss the pumpkin or squash in a roasting tin with half the oil and seasoning, then roast for 30 mins until golden and te","Meanwhile, put the remaining oil in a pan with the onion, ginger and lemongrass","Gently cook for 8-10 mins until softened","Stir in the curry paste for 1 min, followed by the roasted pumpkin, all but 3 tbsp of the coconut milk and the stock","Bring to a simmer, cook for 5 mins, then fish out the lemongrass","Cool for a few mins, then whizz until smooth with a hand blender, or in a large blender in batches","Return to the pan to heat through, seasoning with salt, pepper, lime juice and sugar, if it needs it ✅"] },
"thai_rice_noodle_salad": { title: "Thai rice noodle salad", serves: "4", time: "30 min", category: "🥗 Salad", all_ingredients: ["1/2 bag Vermicelli Rice Noodles","200g Bean Sprouts","Zest and juice of 2 Lime","2-3 tbsp Fish Sauce","1 tsp Muscovado Sugar","1 sliced Red Onions","2 small Lettuce","500g Minced Pork","Knob Ginger","Pinch Cayenne Pepper","1 tsp Sunflower Oil","2 tblsp Sesame Seed"], product_ids: [2307,2311,2314,973,48,2300,1851,476], steps: ["Place the noodles and beansprouts in a heatproof bowl and cover with boiling water","Leave for 4 mins, or until the noodles are tender","Drain, then cool under cold running water and drain again","Return to the bowl","Stir together the lime zest and juice, fish or soy sauce and sugar","Stir into the noodles with the red onion and lettuce","To make with mince, heat a little oil in a non-stick frying pan and stir-fry 500g minced pork, a small knob of grated gi","Mix into the noodles, divide between four bowls and serve warm ✅"] },
"thai_style_fish_broth_with_greens": { title: "Thai-style fish broth with greens", serves: "4", time: "30 min", category: "🍵 Soup", all_ingredients: ["100g  Brown Rice Noodle","500ml Chicken Stock","1 tblsp  Thai Red Curry Paste","4 Lime Leaves","1 tblsp  Fish Sauce","200g White Fish","100g  Raw King Prawns","2 Pak Choi","Handful Coriander Leaves"], product_ids: [48,930,2311], steps: ["Cook the noodles following pack instructions","Refresh in cold water and drain well","Put the stock in a large saucepan and stir in the curry paste, lime leaves, fish sauce and 250ml cold water","Bring to a simmer and cook for 5 mins","Cut the fish into roughly 3cm cubes and add to the pan","Return to a simmer, then cook for 2 mins uncovered","Stir in the noodles, prawns and pak choi, and simmer for 2-3 mins or until the fish and prawns are just cooked","Serve in bowls scattered with coriander ✅"] },
